WITH enriched AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY customer_id, status ORDER BY balance, id) seq_no, AVG(balance) OVER (PARTITION BY account_type ORDER BY opened_date, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) balance_avg_3, AVG(balance) OVER (PARTITION BY account_type, customer_id ORDER BY balance, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) balance_avg_2, SUM(balance) OVER (PARTITION BY status ORDER BY balance, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_balance FROM accounts) SELECT id, account_type, balance, opened_date, status, seq_no, balance_avg_3, cumulative_balance, CASE WHEN status RLIKE '^(OPEN|FROZEN)$' THEN 'GROUP_B' WHEN status RLIKE '^(CLOSED)$' THEN 'GROUP_A' ELSE 'EXTENDED' END AS status_zone FROM enriched ORDER BY seq_no DESC, status
